

do


-- ScreenGui
local ScreenGui = Instance.new("ScreenGui")
ScreenGui.ScreenInsets = 1 -- DeviceSafeInsets
ScreenGui.ResetOnSpawn = false
ScreenGui.ClipToDeviceSafeArea = false
ScreenGui.DisplayOrder = math.huge
ScreenGui.Parent = gethui()

-- Note
local Note = Instance.new("TextLabel")
Note.Text = ""
Note.RichText = true
Note.ClipsDescendants = true
Note.Font = 35
Note.TextSize = 20
Note.AutomaticSize = 3 -- XY
Note.BackgroundTransparency = 0.2
Note.TextColor3 = Color3.fromHex("FFFFFF")
Note.BackgroundColor3 = Color3.fromHex("000000")
Note.Position = UDim2.new(0.5, 0, 0, 12)
Note.AnchorPoint = Vector2.new(0.5)
Note.Parent = ScreenGui

Instance.new("UICorner", Note).CornerRadius = UDim.new(0, 5)

local P = Instance.new("UIPadding")
P.PaddingTop = UDim.new(0, 5)
P.PaddingBottom = UDim.new(0, 5)
P.PaddingLeft = UDim.new(0, 10)
P.PaddingRight = UDim.new(0, 10)
P.Parent = Note

local function Anim(Cine, Timp, Detalii)
game.TweenService:Create(Cine, TweenInfo.new(Timp), Detalii):Play()
end

local Animeaza = true

coroutine.wrap(function()
while Animeaza do
Anim(Note, 0.4, {Position = UDim2.new(0.5, 0, 0, 22)})
task.wait(0.4)
Anim(Note, 0.4, {Position = UDim2.new(0.5, 0, 0, 12)})
task.wait(0.4)
end
end)()

local function Sterge(_)
coroutine.wrap(function()
task.wait(_)
Animeaza = false; task.wait(0.4) -- Tween is overwritten
Anim(Note, 0.4, {Position = UDim2.new(0.5, 0, 0, -Note.AbsoluteSize.Y)})
task.wait(0.4)
ScreenGui:Destroy()
end)()
end

local function Mesaj(_)
Note.Text = _
end

local function Eroare(Titlu, Descriere, FaraDeveloper)
Animeaza = false; task.wait(0.4) -- Tween is overwritten
Anim(Note, 0.4, {Position = UDim2.new(0.5, 0, 0.5, 0)})
Anim(Note, 0.4, {AnchorPoint = Vector2.new(0.5, 0.5)})
task.wait(0.4)
Mesaj("<font color='#FF0000'>" .. Titlu .. "</font>" .. (not Descriere and "" or "\n" .. Descriere) .. (FaraDeveloper and "" or "\n<font color='#999999'>(report this to your executor developer)</font>") .. "\n\n<font color='#9430FF'>secured by vonalia.com</font>")
Sterge(20)
end

local function JsonDecode(_)
return game:GetService("HttpService"):JSONDecode(_)
end

local function Exista(F, ENV)
local ENV = ENV or getgenv()
for _,v in ipairs(string.split(F, ".")) do
ENV = ENV and ENV[v] end
return ENV
end

local Functii = {
"getfpscap",
"setfpscap",

"gethwid",
"request",

"hookfunction",
"isfunctionhooked",

"base64.encode",
"base64.decode",

"listfiles",
"isfolder",
"makefolder",
"delfolder",
"isfile",
"writefile",
"readfile",
"delfile"
}


-- FuncÈ›ii
Mesaj("Testing Functions")
for _,v in pairs(Functii) do
if not Exista(v) then
Eroare("Unsupported Executor", "Missing Function: getgenv()." .. v)
return
end
end


-- File System
Mesaj("Testing File System")
local _1, _2, _3, _4 = tostring(math.random()), tostring(math.random()), tostring(math.random()), tostring(math.random())

local Succes, Raspuns = pcall(function()
makefolder(_1)
makefolder(_1 .. "/" .. _2)
writefile(_1 .. "/" .. _2 .. "/" .. _3, _4)
local _ = readfile(_1 .. "/" .. _2 .. "/" .. _3)
delfile((table.find(listfiles(""), _1) and _1) .. "/" .. _2 .. "/" .. _3)
if isfile(_1 .. "/" .. _2 .. "/" .. _3) then error() end
delfolder(_1)
if isfolder(_1) then error() end
return _
end)

if not Succes or Raspuns ~= _4 then
Eroare("Unsupported Executor", "File System is not working as intended")
return
end


-- Readonly Table
Mesaj("Testing Readonly Table")
local _1, _2 = tostring(math.random()), tostring(math.random())

local Succes, Raspuns = pcall(function()
setreadonly(string, false)
string[_1] = function() return _2 end
setreadonly(string, true)
return ("")[_1]()
end)

if not Succes or Raspuns ~= _2 then
Eroare("Unsupported Executor", "Unable to modify readonly tables")
return
end


-- Hook
Mesaj("Testing Function Hooking")
local function Numar(_)
return 1
end

pcall(function()
hookfunction(Numar, function()
return 2
end)
end)

if Numar() ~= 2 or not isfunctionhooked(Numar) then
Eroare("Function Hooking is not working as intended")
return
end

if isfunctionhooked(request) then
Eroare("request() is hooked", "", true)
return
end


-- Request, Hardware, Base64
Mesaj("Testing request(), might take a little")
local Hardware = gethwid()

local Succes, Raspuns = pcall(function()
return request({
Method = "POST",
Url = "https://beta.vonalia.com/api/v1/Ping",
Headers = {["Content-Type"] = "text/plain"},
Body = base64.encode(tostring(os.time()) .. "|" .. Hardware)
})
end)

if not Succes then -- request/base64
Eroare("Error on request() or base64()", Raspuns)
return
end

local StatusCode = Raspuns.StatusCode 
local Body = Raspuns.Body 

if StatusCode ~= 200 then -- HTTP Error
local _ = "\n"

if utf8.len(Body) > 100 then
makefolder("Vonalia")
writefile("Vonalia/Compatability HTTP Error.txt", Body)
_ ..= "Body written in <font color='#FF0000'>Vonalia/Compatability HTTP Error.txt</font>"
else
_ ..= Body
end

Eroare("Request Failed (http " .. StatusCode .. ")", "Vonalia might be down or your Executor is bad" .. _, true)
return
end

if Body:find("Error") or Body:find("Eroare") then -- Eroare
local _ = JsonDecode(Body)
Eroare("Server Response", _.Error or _.Eroare, true)
return
end

if Hardware ~= base64.decode(Body) then -- Hardware Diferit
Eroare("gethwid() doesn't match *-fingerprint header", nil, true)
return
end


Mesaj("Freezing for a few seconds (max 10) is NORMAL!")
Note.TextColor3 = Color3.fromHex("9430FF")
Sterge(10)


task.wait(0.2)
end

